SELECT a.admission_type_id, a.length_of_stay, p.gender_code, COUNT(DISTINCT a.subject_id) AS patient_count, AVG(m.measurement_value_numeric) AS average_measurement FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN chartevents c ON a.subject_id = c.subject_id AND a.hadm_id = c.hadm_id JOIN measurements m ON c.charttime = m.measurement_time AND c.itemid = m.measurement_id WHERE a.discharge_status_id = 2 AND m.measurement_value_numeric IS NOT NULL GROUP BY a.admission_type_id, a.length_of_stay, p.gender_code ORDER BY a.admission_type_id, a.length_of_stay, p.gender_code NULLS LAST;